using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AbyssalShatterAction", menuName = "Data/Battle/Battle Actions/Cellarius/AbyssalShatter Action")]
public class AbyssalShatterAction : BattleAction
{
	[Header("Purify With Bad Effect Action")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private LoseHeartAction loseHeartAction;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	public PurifyAction PurifyAction => purifyAction;

	public LoseHeartAction LoseHeartAction => loseHeartAction;

	public int GetPurificationAmount(int amount)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentPlayerHearts == 1)
		{
			return amount * 2;
		}
		return amount;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetAmountVFXDelay(target, amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		purifyAction.CastTargetAmount(target, GetPurificationAmount(amount), source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			loseHeartAction.Cast(source);
		});
	}

	private IEnumerator CastTargetAmountVFXDelay(GameObject target, int amount, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		SpawnSecondVFXOnPlayerPosition(3f);
		yield return new WaitForSeconds(vfxDelay);
		purifyAction.CastTargetAmount(target, GetPurificationAmount(amount), source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		yield return new WaitForSeconds(0.1f);
		loseHeartAction.Cast(source);
	}
}
